<?php require_once __DIR__.'/../config/bootstrap.php';$codigo=trim($_GET['codigo']??'');$cert=null;if($codigo){$s=db()->prepare('SELECT ce.*,u.nome,c.titulo,c.carga_horaria FROM certificates ce JOIN users u ON u.id=ce.user_id JOIN courses c ON c.id=ce.course_id WHERE ce.codigo=? LIMIT 1');$s->execute([$codigo]);$cert=$s->fetch();} ?>
<?php layout_header('Verificar certificado'); ?><div class="auth-card"><a class="auth-back" href="<?=e(url())?>">← Voltar</a><h1>Verifique seu certificado</h1><p class="subtitle">Informe o código de autenticação.</p><form method="get"><label>Código</label><input name="codigo" value="<?=e($codigo)?>" placeholder="Ex.: HC-XXXXXXXXXXX" required><button class="btn">Consultar</button></form><?php if($codigo): ?><div class="verify-result <?=$cert&&$cert['status']==='active'?'valid':'invalid'?>"><?php if($cert&&$cert['status']==='active'): ?><h2>✓ Certificado válido</h2><p><strong>Aluno:</strong> <?=e($cert['nome'])?></p><p><strong>Curso:</strong> <?=e($cert['titulo'])?></p><p><strong>Carga horária:</strong> <?=e($cert['carga_horaria'])?> horas</p><p><strong>Emitido em:</strong> <?=e(date('d/m/Y H:i',strtotime($cert['issued_at'])))?></p><p><strong>Validade:</strong> <?=e(date('d/m/Y',strtotime($cert['validade'])))?></p><p><strong>Código:</strong> <?=e($cert['codigo'])?></p><?php else: ?><h2>✕ Certificado não encontrado</h2><p>Confira o código informado.</p><?php endif; ?></div><?php endif; ?></div><?php layout_footer(); ?>
